<script lang="ts">
  import { onMount } from 'svelte';
  import { game } from '../../../gameManager.js';
  import type { GameRuntime } from '../../types/game.js';
  import { buildSubwayTrainerPreviewsForToday } from '../../lib/subwayTrainerPreview.ts';
  import { useGameLanguageTick } from '../../lib/useGameLanguageTick.svelte.ts';
  import { bindHorizontalEdgeAutoScroll, stopHorizontalEdgeAutoScroll } from '../../ui/navigation.ts';
  import SubwayOpponentPokemonCard from './SubwayOpponentPokemonCard.svelte';
  import SubwayOpponentPokemonDetail from './SubwayOpponentPokemonDetail.svelte';

  const { trackGameLanguage } = useGameLanguageTick();

  let selectedTrainerIndex = $state(0);
  let selectedPokemonIndex = $state(0);
  let trainerStripEl = $state<HTMLDivElement | undefined>(undefined);

  onMount(() => {
    if (!trainerStripEl) return;
    bindHorizontalEdgeAutoScroll(trainerStripEl, {
      datasetKey: 'edgeScrollBoundSubway',
      chipSelector: '.tower-subway-trainer-chip',
    });
    return () => stopHorizontalEdgeAutoScroll(trainerStripEl!);
  });

  const dailyPreview = $derived.by(() => {
    trackGameLanguage();
    const gm = game as GameRuntime | null;
    if (!gm) return null;
    return buildSubwayTrainerPreviewsForToday(gm);
  });

  const previews = $derived(dailyPreview?.trainers ?? []);

  const selectedTrainer = $derived(previews[selectedTrainerIndex] ?? null);
  const selectedPokemon = $derived(selectedTrainer?.team[selectedPokemonIndex] ?? null);

  function t(key: string, fallback: string, vars?: Record<string, string | number>): string {
    trackGameLanguage();
    const gm = game as GameRuntime | null;
    if (!gm?.t) return applyVars(fallback, vars);
    const out = gm.t(key, vars);
    return out && out !== key ? out : applyVars(fallback, vars);
  }

  function applyVars(template: string, vars?: Record<string, string | number>): string {
    if (!vars) return template;
    return template.replace(/\{(\w+)\}/g, (_, k) => String(vars[k] ?? ''));
  }

  function selectTrainer(index: number) {
    selectedTrainerIndex = index;
    selectedPokemonIndex = 0;
  }
</script>

{#if previews.length > 0}
  <div class="tower-subway-trainer-dex">
    <h4 id="subwayTrainerDexTitle" class="tower-subway-trainer-dex__title">
      {t('subway.trainerDexTitle', 'Dresseurs du wagon')}
    </h4>
    {#if dailyPreview}
      <div class="tower-subway-daily-banner">
        <span class="tower-subway-daily-banner__text">
          {t('subway.dailySetBanner', 'Set du jour : {label}', { label: dailyPreview.label })}
        </span>
        <span class="type-badge type-{dailyPreview.themeType}">{dailyPreview.themeType}</span>
      </div>
    {/if}
    <p class="tower-subway-trainer-dex__hint">
      {t('subway.trainerDexHint', 'Cliquez un dresseur, puis un Pokémon pour voir son set.')}
    </p>

    <div
      class="tower-subway-trainer-strip"
      role="tablist"
      aria-label={t('subway.trainerDexTitle', 'Dresseurs du wagon')}
      bind:this={trainerStripEl}
    >
      {#each previews as trainer, idx (trainer.id)}
        <button
          type="button"
          role="tab"
          class="elite-four-trainer-chip tower-subway-trainer-chip"
          class:active={selectedTrainerIndex === idx}
          aria-selected={selectedTrainerIndex === idx}
          onclick={() => selectTrainer(idx)}
        >
          <img
            src={trainer.spriteUrl}
            alt=""
            class="elite-four-trainer-sprite"
            onerror={(e) => { (e.currentTarget as HTMLImageElement).style.display = 'none'; }}
          />
          <span class="tower-subway-trainer-chip__text">
            <span class="tower-subway-battle-badge">
              {t('subway.battleLabel', 'Combat {n}/7', { n: trainer.battleIndex })}
            </span>
            <span class="elite-four-trainer-name">{trainer.name}</span>
            {#if trainer.useUltimates}
              <span class="tower-subway-ult-indicator" title={t('subway.ultimatesEnabled', 'Peut utiliser son ultime')}>⚡</span>
            {/if}
          </span>
        </button>
      {/each}
    </div>

    {#if selectedTrainer}
      <div class="tower-subway-trainer-panel" role="tabpanel">
        <div class="tower-subway-trainer-panel__header">
          <img src={selectedTrainer.spriteUrl} alt="" class="tower-subway-trainer-panel__sprite" />
          <div>
            <strong>{selectedTrainer.name}</strong>
            <div class="tower-subway-trainer-panel__type">
              <span class="type-badge type-{selectedTrainer.specialtyType}">{selectedTrainer.specialtyType}</span>
            </div>
          </div>
        </div>

        <h5 class="tower-subway-team-label">{t('subway.teamLabel', 'Équipe')}</h5>
        <div class="tower-subway-team-grid">
          {#each selectedTrainer.team as mon, pIdx (mon.name)}
            <SubwayOpponentPokemonCard
              pokemon={mon}
              selected={selectedPokemonIndex === pIdx}
              onclick={() => { selectedPokemonIndex = pIdx; }}
            />
          {/each}
        </div>

        {#if selectedPokemon}
          <SubwayOpponentPokemonDetail trainer={selectedTrainer} pokemon={selectedPokemon} />
        {/if}
      </div>
    {/if}
  </div>
{/if}
