<script lang="ts">
  import type { SubwayPokemonPreview } from '../../lib/subwayTrainerPreview.ts';
  import { getHeldItem } from '../../ui/uiItems.ts';
  import { uiText } from '../../ui/i18n.ts';
  import { touchTooltipHandlers } from '../../ui/scheduleTooltipHelpers.ts';

  let {
    pokemon,
    selected = false,
    onclick,
  }: {
    pokemon: SubwayPokemonPreview;
    selected?: boolean;
    onclick?: () => void;
  } = $props();

  const heldItem = $derived(pokemon.heldItem ? getHeldItem(pokemon.heldItem.key) : null);
  const levelLabel = $derived(
    uiText('subway.indicativeLevel', 'Niv. ~{level}', { level: pokemon.indicativeLevel }),
  );
  const heldItemTooltip = $derived(
    pokemon.heldItem
      ? touchTooltipHandlers(() => ({
          title: pokemon.heldItem!.name,
          body: pokemon.heldItem!.description,
        }))
      : null,
  );
</script>

<button
  type="button"
  class="creature-card tower-subway-pokemon-card"
  class:tower-subway-pokemon-card--selected={selected}
  onclick={onclick}
  aria-pressed={selected}
>
  <img
    src={pokemon.spriteUrl}
    alt=""
    class="team-slot-sprite"
    draggable="false"
    onerror={(e) => { (e.currentTarget as HTMLImageElement).src = 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/versions/generation-v/black-white/substitute.png'; }}
  />
  {#if heldItem?.img}
    <!-- svelte-ignore a11y_click_events_have_key_events -->
    <!-- svelte-ignore a11y_no_noninteractive_element_interactions -->
    <img
      src={heldItem.img}
      class="creature-card-held-item"
      alt={pokemon.heldItem?.name ?? ''}
      onmouseenter={heldItemTooltip?.onmouseenter}
      onmouseleave={heldItemTooltip?.onmouseleave}
      onfocus={heldItemTooltip?.onfocus}
      onblur={heldItemTooltip?.onblur}
      onclick={(e) => { e.stopPropagation(); heldItemTooltip?.onclick?.(e); }}
    />
  {:else if heldItem?.icon}
    <!-- svelte-ignore a11y_click_events_have_key_events -->
    <!-- svelte-ignore a11y_no_noninteractive_element_interactions -->
    <!-- svelte-ignore a11y_no_noninteractive_tabindex -->
    <span
      class="creature-card-held-item creature-card-held-item-icon"
      onmouseenter={heldItemTooltip?.onmouseenter}
      onmouseleave={heldItemTooltip?.onmouseleave}
      onfocus={heldItemTooltip?.onfocus}
      onblur={heldItemTooltip?.onblur}
      onclick={(e) => { e.stopPropagation(); heldItemTooltip?.onclick?.(e); }}
      role="img"
      tabindex="-1"
    >
      {heldItem.icon}
    </span>
  {/if}
  <h4 class="tower-subway-pokemon-card__name">{pokemon.displayName}</h4>
  <div class="tower-subway-pokemon-card__meta">
    <span class="type-badge type-{pokemon.primaryType}">{pokemon.primaryType}</span>
    <span class="tower-subway-pokemon-card__level">{levelLabel}</span>
  </div>
</button>
