<script lang="ts">
  import { tower } from '../stores/tower.svelte.ts';
  import TowerAscentMemoryContent from './tower/TowerAscentMemoryContent.svelte';
  import TowerBatchContent from './tower/TowerBatchContent.svelte';
  import TowerRelicAutoContent from './tower/TowerRelicAutoContent.svelte';
  import TowerSubwayContent from './tower/TowerSubwayContent.svelte';
  import TowerChampionsContent from './tower/TowerChampionsContent.svelte';

  let snap = $derived(tower.snapshot);
  let activePanel = $state<'tower' | 'subway' | 'champions'>('tower');

  const hasExtraTabs = $derived(snap.subwayTabVisible || snap.championsTabVisible);

  $effect(() => {
    if (!snap.subwayTabVisible && activePanel === 'subway') {
      activePanel = snap.championsTabVisible ? 'champions' : 'tower';
    }
    if (!snap.championsTabVisible && activePanel === 'champions') {
      activePanel = 'tower';
    }
  });
</script>

<!-- Cible = #towerTab -->
{#if hasExtraTabs}
  <div class="tower-subtab-row">
    <button
      type="button"
      class="tower-subtab-btn"
      class:active={activePanel === 'tower'}
      data-action="switchTowerPanel"
      data-arg="tower"
      onclick={() => { activePanel = 'tower'; }}
    >{snap.titleLabel}</button>
    {#if snap.subwayTabVisible}
      <button
        type="button"
        class="tower-subtab-btn"
        class:active={activePanel === 'subway'}
        data-action="switchTowerPanel"
        data-arg="subway"
        onclick={() => { activePanel = 'subway'; }}
      >{snap.subwayTitleLabel}</button>
    {/if}
    {#if snap.championsTabVisible}
      <button
        type="button"
        class="tower-subtab-btn"
        class:active={activePanel === 'champions'}
        data-action="switchTowerPanel"
        data-arg="champions"
        onclick={() => { activePanel = 'champions'; }}
      >{snap.championsTitleLabel}</button>
    {/if}
  </div>
{/if}

<div style="text-align: center; margin-bottom: 12px;">
  <div class="tower-stats">
    <div><img src="https://raw.githubusercontent.com/msikma/pokesprite/master/items/key-item/crown-pass.png" class="combat-ticket-inline" alt="" loading="lazy" decoding="async" fetchpriority="low"> <span id="towerTicketsLabel">{snap.ticketsLabel}</span> <strong id="combatTickets">{snap.combatTickets}</strong></div>
  </div>
</div>

{#if activePanel === 'champions' && snap.championsTabVisible}
  <TowerChampionsContent />
{:else if activePanel === 'subway' && snap.subwayTabVisible}
  <TowerSubwayContent />
{:else}
  <h3 id="towerTitleLabel">{snap.titleLabel}</h3>
  <div style="text-align: center; margin-bottom: 20px;">
    <div class="tower-stats">
      <div><span id="towerRecordLabel">{snap.recordLabel}</span> <strong id="towerRecord">{snap.towerRecord}</strong></div>
      <div><img src="https://raw.githubusercontent.com/msikma/pokesprite/master/items/valuable-item/relic-crown.png" class="marque-triomphe-inline" alt="" loading="lazy" decoding="async" fetchpriority="low"> <span id="towerMarksLabel">{snap.marksLabel}</span> <strong id="triumphMarks">{snap.triumphMarks}</strong></div>
    </div>
    <button id="towerStartBtn" class="btn btn-save" data-action="startTowerRun" disabled={snap.startDisabled}>
      <span id="towerStartLabel">{@html snap.startLabelHtml}</span>
    </button>
    {#if snap.batchVisible || snap.ascentMemoryVisible}
      <div class="tower-options-row">
        <TowerBatchContent />
        <TowerAscentMemoryContent />
      </div>
    {/if}
    <TowerRelicAutoContent />
  </div>
{/if}
