<script lang="ts">
  import { game } from '../../../gameManager.js';
  import type { SubwayPokemonPreview } from '../../lib/subwayTrainerPreview.ts';
  import type { SubwayTrainerPreview } from '../../lib/subwayTrainerPreview.ts';
  import type { GameRuntime } from '../../types/game.js';
  import { getMoveDefinition } from '../../../constants/movesDb.ts';
  import { formatMoveAccuracyRowLabel } from '../../lib/moveTooltip.ts';
  import { uiText } from '../../ui/i18n.ts';
  import { formatNumber } from '../../../formatters.js';

  let {
    trainer,
    pokemon,
  }: {
    trainer: SubwayTrainerPreview;
    pokemon: SubwayPokemonPreview;
  } = $props();

  const STAT_ROWS = [
    { key: 'hp' as const, labelKey: 'header.statHp', fallback: 'HP :' },
    { key: 'attack' as const, labelKey: 'header.statAtk', fallback: 'ATK :' },
    { key: 'defense' as const, labelKey: 'header.statDef', fallback: 'DEF :' },
    { key: 'spAttack' as const, labelKey: 'header.statSpAtk', fallback: 'ATK SP :' },
    { key: 'spDefense' as const, labelKey: 'header.statSpDef', fallback: 'DEF SP :' },
    { key: 'speed' as const, labelKey: 'header.statSpd', fallback: 'SPD :' },
  ];

  const primaryMoveColors = $derived.by(() => {
    const first = pokemon.moves[0];
    return first ? { bg: first.bg, text: first.text } : { bg: '#868e96', text: '#fafafa' };
  });

  const ultStatus = $derived.by(() => {
    if (pokemon.canUseUltimate) {
      return uiText('subway.ultimatesEnabled', 'Peut utiliser son ultime');
    }
    return uiText('subway.ultimatesBlockedItem', 'Ultime bloqué par l\'objet tenu');
  });

  function powerShortLabel(): string {
    const gm = game as GameRuntime | null;
    if (gm?.t) {
      const out = gm.t('modal.creature.powerShort');
      if (out && out !== 'modal.creature.powerShort') return out;
    }
    return 'Pow.';
  }

  function moveAccuracyLabel(moveName: string): string {
    const gm = game as GameRuntime | null;
    if (!gm) return 'Préc. 100';
    const def = getMoveDefinition(moveName);
    return formatMoveAccuracyRowLabel(gm, (def ?? {}) as Record<string, unknown>);
  }
</script>

<article class="tower-subway-pokemon-detail">
  <div class="tower-subway-pokemon-detail__header">
    <div class="tower-subway-pokemon-detail__identity">
      <div class="creature-modal-sprite-wrap tower-subway-pokemon-detail__sprite-wrap">
        <img src={pokemon.spriteUrl} alt="" class="creature-modal-sprite" />
        <div class="creature-modal-badges-types">
          <span class="type-badge type-{pokemon.primaryType}">{pokemon.primaryType}</span>
          {#if pokemon.secondaryType}
            <span class="type-badge type-{pokemon.secondaryType}">{pokemon.secondaryType}</span>
          {/if}
        </div>
      </div>
      <div class="tower-subway-pokemon-detail__title">
        <h4>{pokemon.displayName}</h4>
        <p class="tower-subway-pokemon-detail__level">
          {uiText('subway.indicativeLevel', 'Niv. ~{level}', { level: pokemon.indicativeLevel })}
        </p>
      </div>
    </div>
  </div>

  <div class="creature-modal-info tower-subway-pokemon-detail__body">
    <section class="tower-subway-detail-section tower-subway-moves-section">
      <h5
        class="creature-modal-move-title tower-subway-moves-section__title"
        style="color: {primaryMoveColors.bg};"
      >
        {uiText('subway.movesLabel', 'Attaques')}
      </h5>
      <div class="creature-moves-list tower-subway-moves-list">
        {#each pokemon.moves as move (move.name)}
          {@const moveCategoryClass = move.category === 'special' ? 'special' : 'physical'}
          <div
            class="creature-move-row tower-subway-move-row"
            data-move-tooltip-name={move.name}
            style="background:{move.bg}; color:{move.text}; border:2px solid {move.bg};"
          >
            <div class="creature-move-row__left">
              <span
                class="move-pill"
                style="background:rgba(255,255,255,0.2); color:{move.text}; margin:0; padding:2px 6px; font-size:9px; line-height:1;"
              >{move.displayName}</span>
            </div>
            <div class="creature-move-row__right">
              <span class="move-category {moveCategoryClass}" style="margin:0; filter:brightness(1.5);">{move.category}</span>
              <span class="move-power" style="margin:0; color:{move.text};">{powerShortLabel()} {move.power}</span>
              <span class="move-accuracy" style="margin:0; font-size:10px; color:{move.text};">{moveAccuracyLabel(move.name)}</span>
            </div>
          </div>
        {/each}
      </div>
    </section>

    {#if pokemon.talent}
      <section class="tower-subway-detail-section tower-subway-talent-block">
        <strong>{uiText('subway.talentLabel', 'Talent')} : {pokemon.talent.name}</strong>
        <p>{pokemon.talent.description}</p>
      </section>
    {/if}

    <section class="tower-subway-detail-section tower-subway-ultimate-block">
      <strong>
        {uiText('subway.ultimateLabel', 'Ultime')} : {pokemon.ultimate.name}
        ({pokemon.ultimate.chargeNeeded})
      </strong>
      <p>{pokemon.ultimate.description}</p>
      <span class="tower-subway-ult-badge" class:tower-subway-ult-badge--on={pokemon.canUseUltimate}>
        {ultStatus}
      </span>
    </section>

    <section class="tower-subway-detail-section">
      <h5>{uiText('subway.statsLabel', 'Stats indicatives')}</h5>
      <div class="tower-subway-stats-grid">
        {#each STAT_ROWS as row (row.key)}
          <div class="tower-subway-stat-row">
            <span class="tower-subway-stat-label">{uiText(row.labelKey, row.fallback)}</span>
            <span class="tower-subway-stat-value">{formatNumber(pokemon.indicativeStats[row.key])}</span>
          </div>
        {/each}
      </div>
    </section>
  </div>
</article>
