<script lang="ts">
  /* eslint-disable svelte/no-at-html-tags -- ascent memory panel from towerSnapshot */
  import { tower } from '../../stores/tower.svelte.ts';
  import { game } from '../../../gameManager.js';
  import { bindTowerAscentMemoryPanelEvents } from '../../../towerSystem.js';

  let snap = $derived(tower.snapshot);
  let panelEl: HTMLDivElement | undefined = $state();

  $effect(() => {
    snap.ascentMemoryHtml;
    const sig = snap.ascentMemorySig;
    const el = panelEl;
    const gm = game;
    if (!el || !sig || !gm) return;
    bindTowerAscentMemoryPanelEvents(el, gm);
  });
</script>

<div
  bind:this={panelEl}
  id="towerAscentMemoryPanel"
  class="tower-ascent-memory-panel"
  style:display={snap.ascentMemoryVisible ? '' : 'none'}
  aria-live="polite"
>
  <!-- svelte-ignore a11y_no_static_element_interactions -->
  {@html snap.ascentMemoryHtml}
</div>
