/**
 * @file subwayTrainerPreview.ts
 * Static preview data for Battle Subway trainer dex UI.
 */

import type { GameRuntime } from '../types/game.js';
import type { CreatureData } from '../types/creature.js';
import { RARITY, POKEMON_SECONDARY_TYPES } from '../../constants/core.ts';
import {
    type SubwayTrainerDef,
    type SubwayTrainerPokemon,
} from '../../constants/balance/subwayTrainers.ts';
import { getSubwayDailySet, getSubwayTrainersForDay } from './subwayDailySet.ts';
import { HELD_ITEMS } from '../../constants/balance/towerAndItems.ts';
import { PASSIVE_TALENTS } from '../../constants/balance/talentsAndCombat.ts';
import { pickTrainerMoves } from './trainerMovesets.ts';
import { resolveUltimateAbility, scaleUltimateChargeForEnemyPvp } from './resolveUltimateAbility.ts';
import { getPokemonSpriteUrl } from './cardSprites.ts';
import { buildMovePillDisplay, type MovePillDisplay } from './movePillDisplay.ts';
import { getLocalizedHeldItemDescription, getLocalizedHeldItemLabel, uiPokemonNameText } from '../ui/i18n.ts';
import { generateSubwayTrainerTeamLogic, getSubwayPreviewLevel } from './subwayCombatTeam.ts';
import { getSubwayTrainerSpriteUrl } from './subwayTrainerSpriteUrl.ts';

function isHeldItemBlockingUltimate(heldItemKey: string | undefined): boolean {
    if (!heldItemKey) return false;
    const heldDef = (HELD_ITEMS as Record<string, { effect?: { disable_ultimate?: boolean } }>)[heldItemKey];
    return !!(heldDef?.effect?.disable_ultimate);
}

export interface SubwayPokemonIndicativeStats {
    hp: number;
    attack: number;
    defense: number;
    spAttack: number;
    spDefense: number;
    speed: number;
}

export interface SubwayPokemonPreview {
    name: string;
    displayName: string;
    spriteUrl: string;
    primaryType: string;
    secondaryType: string | null;
    indicativeLevel: number;
    indicativeStats: SubwayPokemonIndicativeStats;
    moves: MovePillDisplay[];
    talent: { key: string; name: string; description: string } | null;
    heldItem: { key: string; name: string; description: string } | null;
    ultimate: { name: string; description: string; chargeNeeded: number };
    canUseUltimate: boolean;
}

export interface SubwayTrainerPreview {
    id: string;
    battleIndex: number;
    name: string;
    spriteUrl: string;
    specialtyType: string;
    useUltimates: boolean;
    team: SubwayPokemonPreview[];
}

export interface SubwayDailySetPreview {
    dayIndex: number;
    themeType: string;
    label: string;
    trainers: SubwayTrainerPreview[];
}

function resolveSubwayLang(game: GameRuntime): 'fr' | 'en' {
    if (typeof game.normalizeLanguage === 'function') {
        return game.normalizeLanguage(game.language) === 'en' ? 'en' : 'fr';
    }
    return game.language === 'en' ? 'en' : 'fr';
}

function resolveEntryRarity(entry: SubwayTrainerPokemon): string {
    if (entry.rarity === 'epic') return RARITY.EPIC;
    return RARITY.RARE;
}

function resolveTalentPreview(
    game: GameRuntime,
    talentKey: string | undefined,
): { key: string; name: string; description: string } | null {
    if (!talentKey) return null;
    const def = (PASSIVE_TALENTS as Record<string, { name?: string; description?: string }>)[talentKey];
    if (!def) return null;
    const name = typeof game.getLocalizedPassiveTalentName === 'function'
        ? game.getLocalizedPassiveTalentName(talentKey, def.name ?? talentKey)
        : (def.name ?? talentKey);
    const description = typeof game.getLocalizedPassiveTalentDescription === 'function'
        ? game.getLocalizedPassiveTalentDescription(talentKey, def.description ?? '')
        : (def.description ?? '');
    return { key: talentKey, name, description };
}

function resolveHeldItemPreview(
    game: GameRuntime,
    itemKey: string | undefined,
): { key: string; name: string; description: string } | null {
    if (!itemKey) return null;
    const def = (HELD_ITEMS as Record<string, { name?: string; description?: string }>)[itemKey];
    if (!def) return null;
    const name = getLocalizedHeldItemLabel(game, itemKey);
    const description = getLocalizedHeldItemDescription(game, itemKey);
    return { key: itemKey, name, description };
}

function extractIndicativeStats(creature: CreatureData): SubwayPokemonIndicativeStats {
    return {
        hp: creature.maxHp ?? 0,
        attack: creature.attack ?? 0,
        defense: creature.defense ?? 0,
        spAttack: creature.spattack ?? 0,
        spDefense: creature.spdefense ?? 0,
        speed: creature.speed ?? 0,
    };
}

function buildPokemonPreview(
    game: GameRuntime,
    entry: SubwayTrainerPokemon,
    trainer: SubwayTrainerDef,
    battleIndex: number,
    combatStatsByName: Map<string, SubwayPokemonIndicativeStats>,
): SubwayPokemonPreview {
    const pokemonType = entry.type ?? trainer.type;
    const explicitMoves = entry.moves ?? trainer.fixedMovesets?.[entry.name] ?? null;
    const moveNames = pickTrainerMoves(
        entry.name,
        pokemonType,
        explicitMoves,
        { ensureTypeDiversity: !explicitMoves },
    );
    const rarity = resolveEntryRarity(entry);
    const ultimate = scaleUltimateChargeForEnemyPvp(resolveUltimateAbility(entry.name, rarity));
    const heldItemKey = entry.heldItem && (HELD_ITEMS as Record<string, unknown>)[entry.heldItem]
        ? entry.heldItem
        : undefined;
    const ultimateName = typeof game.getLocalizedUltimateName === 'function'
        ? game.getLocalizedUltimateName(entry.name, ultimate.name ?? '')
        : (ultimate.name ?? '');
    const ultimateDescription = typeof game.getLocalizedUltimateDescription === 'function'
        ? game.getLocalizedUltimateDescription(entry.name, ultimate.description ?? '')
        : (ultimate.description ?? '');
    const ultBlocked = heldItemKey ? isHeldItemBlockingUltimate(heldItemKey) : false;
    const combatStats = combatStatsByName.get(entry.name) ?? {
        hp: 0, attack: 0, defense: 0, spAttack: 0, spDefense: 0, speed: 0,
    };

    return {
        name: entry.name,
        displayName: uiPokemonNameText(game, entry.name),
        spriteUrl: getPokemonSpriteUrl(entry.name, false, { preferStatic: true }),
        primaryType: pokemonType,
        secondaryType: POKEMON_SECONDARY_TYPES[entry.name] ?? null,
        indicativeLevel: getSubwayPreviewLevel(game, battleIndex, entry.levelOffset ?? 0),
        indicativeStats: combatStats,
        moves: moveNames.map((m) => buildMovePillDisplay(game, m)),
        talent: resolveTalentPreview(game, entry.talent),
        heldItem: resolveHeldItemPreview(game, heldItemKey),
        ultimate: {
            name: ultimateName,
            description: ultimateDescription,
            chargeNeeded: ultimate.chargeNeeded ?? 100,
        },
        canUseUltimate: !ultBlocked,
    };
}

function buildTrainerPreviewsFromDefs(
    game: GameRuntime,
    trainers: SubwayTrainerDef[],
): SubwayTrainerPreview[] {
    const lang = resolveSubwayLang(game);
    return trainers.map((trainer, idx) => {
        const battleIndex = idx + 1;
        const useUltimates = trainer.useUltimates ?? false;
        const { team: combatTeam } = generateSubwayTrainerTeamLogic(game, battleIndex, trainers);
        const combatStatsByName = new Map(
            combatTeam.map((c) => [c.name, extractIndicativeStats(c)]),
        );
        return {
            id: trainer.id,
            battleIndex,
            name: trainer.name[lang] ?? trainer.name.fr,
            spriteUrl: getSubwayTrainerSpriteUrl(trainer.spriteKey),
            specialtyType: trainer.type,
            useUltimates,
            team: trainer.team.map((entry) => buildPokemonPreview(
                game,
                entry,
                trainer,
                battleIndex,
                combatStatsByName,
            )),
        };
    });
}

export function buildSubwayTrainerPreviews(
    game: GameRuntime,
    trainers: SubwayTrainerDef[] = getSubwayTrainersForDay(),
): SubwayTrainerPreview[] {
    return buildTrainerPreviewsFromDefs(game, trainers);
}

export function buildSubwayTrainerPreviewsForToday(game: GameRuntime): SubwayDailySetPreview {
    const lang = resolveSubwayLang(game);
    const dailySet = getSubwayDailySet();
    return {
        dayIndex: dailySet.dayIndex,
        themeType: dailySet.themeType,
        label: dailySet.label[lang] ?? dailySet.label.fr,
        trainers: buildTrainerPreviewsFromDefs(game, dailySet.trainers),
    };
}
